out = {"kind": "scale78b sr2 mutation spec (R1 Track S)",
       "note": "each mutant's find text occurs exactly once in its file (the runner refuses otherwise); runner: scripts/scale78b/tests/run_mutants_sr2.py (test_blinded_sigma.py, test_sr2_simulation.py); files are relative to scripts/scale78b",
       "mutants": []}
for mid, f, desc, find, rep in M:
    text = (pkg / f).read_text()
    n = text.count(find)
    if n != 1:
        print("BAD", mid, n)
    out["mutants"].append({"id": mid, "describes": desc, "file": f, "find": find, "replace": rep})
(pkg / "tests/mutation_spec_sr2.json").write_text(json.dumps(out, indent=1, ensure_ascii=False) + "\n")
print(len(M))
